import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color, texture, sin, fract, add, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh, SRGBColorSpace } = ctx.THREE;

  const root = new Group();
  root.userData.handlers = {};

  const timelines = [];
  const disposables = [];

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline') || items[0];
  const headlineText = headlineItem?.text ?? '';
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const atlasW = 512;
  const atlasH = 320;
  const cardW = 2.0;
  const cardH = cardW * (atlasH / atlasW);

  const cardGeo = new PlaneGeometry(cardW, cardH);
  disposables.push(cardGeo);

  const vUv = uv();
  const gradient = mix(color(colors.surface), color(colors.ink), smoothstep(0.0, 1.0, vUv.y));
  const seed = add(mul(vUv.x, 1234.0), mul(vUv.y, 5678.0));
  const noiseVal = sub(fract(mul(sin(seed), 43758.5453)), 0.5).mul(0.05);
  const cardMat = new MeshBasicNodeMaterial();
  cardMat.colorNode = gradient.add(vec3(noiseVal));
  disposables.push(cardMat);

  const cardPlane = new Mesh(cardGeo, cardMat);
  root.add(cardPlane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.needsUpdate = true;

      const imgGeo = new PlaneGeometry(cardW, cardH);
      const imgMat = new MeshBasicNodeMaterial();
      imgMat.transparent = true;
      const texSample = texture(tex, uv());
      imgMat.colorNode = texSample;
      imgMat.opacityNode = texSample.a;
      disposables.push(imgGeo, imgMat, tex);

      const imgPlane = new Mesh(imgGeo, imgMat);
      imgPlane.position.z = 0.01;
      root.add(imgPlane);
    }).catch(() => {});
  }

  if (headlineText) {
    const textObj = ctx.fontAtlas.createText(headlineText, {
      fontSize,
      color: colors.paper,
      align: 'left'
    });
    textObj.position.set(-cardW * 0.42, -cardH * 0.35, 0.02);
    root.add(textObj);
  }

  const accentW = 0.12;
  const accentH = 0.012;
  const accentGeo = new PlaneGeometry(accentW, accentH);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = color(colors.accent);
  disposables.push(accentGeo, accentMat);
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-cardW * 0.42 + accentW * 0.5, -cardH * 0.42, 0.02);
  root.add(accentMesh);

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      const result = ctx.primitives[p.name](root, p.params ?? {});
      if (result?.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.cleanup = () => {
    timelines.forEach(t => { try { t.kill(); } catch (e) {} });
    disposables.forEach(d => { try { d.dispose(); } catch (e) {} });
  };

  return root;
}
